function flowHas(messages,pattern){return messages.some(message=>pattern.test(message))}
function chatgptFailureStep(session,messages){const error=String(session.error||session.message||'').toLowerCase();if(/sub2api|cpa|站点导入|导入失败|group|分组/.test(error))return 8;if(/json|认证文件|auth\.json/.test(error))return 7;if(/access.?token|session|agent identity|private key|agent 注册/.test(error))return 6;if(/account_deactivated|账户.*(?:删除|停用)|账号.*(?:删除|停用)/.test(error))return 3;if(/unsupported_email|email you provided is not supported|不支持当前邮箱/.test(error))return 1;if(/完成账号|资料|about-you|姓名|生日|年龄|profile/.test(error))return 4;if(/验证码|verification|\bcode\b/.test(error))return 3;if(/密码|password/.test(error))return 2;if(/邮箱|email|signup/.test(error))return 1;if(/注册完成|等待注册|completion|passkey|手机号/.test(error))return 5;for(let index=chatgptFlowStepTemplate.length-1;index>=0;index--){if(messages.some(message=>message.includes(`[chatgpt] ${chatgptFlowStepTemplate[index].key}`)))return index}return 0}
