  if(/queued; email=|\[xai\] email: filling/.test(all))states[1]='running';
  if(/solving turnstile|sending email validation code|\[xai\] email: submitted/.test(all))states[1]='done';
  if(/\[xai\] password: (?:filling|filled|refilling)/.test(all))states[2]='running';
  if(/\[xai\] password: submitted|\[xai\] human_verification:|\[xai\] verification:/.test(all))states[2]='done';
  if(/turnstile|过盾|\[xai\] human_verification: (?:detected|waiting|manual|clicked)/.test(all))states[3]='running';
  if(/sending email validation code|waiting for xai verification code|code received|\[xai\] human_verification: (?:passed|passed_after_widget_success|not_required)/.test(all))states[3]='done';
  if(/sending email validation code|waiting for xai verification code|code received|\[xai\] verification: (?:waiting|code_)/.test(all))states[4]='running';
  if(/creating xai account|xai 浏览器注册成功|\[xai\] verification: submitted|\[xai\] completion:/.test(all))states[4]='done';
  if(/creating xai account|\[xai\] profile: submitted|\[xai\] completion: waiting/.test(all))states[5]='running';
  if(/xai 浏览器注册成功|\[xai\] completion: done/.test(all))states[5]='done';
  if(/正在生成本地 xai pkce|\[xai\] local_oauth: opening_authorization|本地 pkce 会话已生成/.test(all))states[6]='running';
  if(/本地 at\/rt 兑换完成|已捕获 xai oauth 回调/.test(all))states[6]='done';
  if(/本地 at\/rt 兑换完成|正在转换 (?:cpa|sub2api) json/.test(all))states[7]='running';
