  if(probeIndex!==undefined){const probeState=String(session.probe?.state||'').toLowerCase();const probeCount=Number(session.probe?.count||0);const probeOk=Number(session.probe?.ok||0);const probeFailed=Number(session.probe?.fail||0)>0||Number(session.probe?.uncertain||0)>0;if(['queued','running','retry_pending'].includes(probeState))states[probeIndex]='running';else if(probeCount>0&&probeOk>=probeCount&&!probeFailed)states[probeIndex]='done';else if(probeCount>0&&probeFailed)states[probeIndex]='failed';}
  if(siteReached)states[siteIndex]=siteDone?'done':'running';
