async function handleManualImportAction(event){const importButton=event.target.closest('[data-manual-import]');const probeButton=event.target.closest('[data-manual-probe]');const button=importButton||probeButton;if(!button||button.disabled)return;const sessionId=button.dataset.manualImport||button.dataset.manualProbe;button.disabled=true;try{const action=importButton?'retry-import':'retry-probe';const result=await api(`/api/sessions/${encodeURIComponent(sessionId)}/${action}`,{method:'POST'});notify(importButton?'已提交手动导入':result.already_running?'该账号正在测活':'已提交账号测活');await refresh()}catch(error){notify(`${importButton?'导入':'测活'}失败：${error.message}`)}finally{button.disabled=false}}
