function concurrentWorkflowHtml(items){if(!items.length)return'<div class="empty">启动任务后显示固定注册流程</div>';if(items.length===1)return fixedWorkflowHtml(items[0].workflow);return items.map(({session,workflow})=>{const current=workflowCurrentStep(workflow);const dots=workflow.steps.map(step=>`<span class="concurrent-flow-dot ${step.state}" title="步骤 ${step.number}：${escapeHtml(step.title)}">${step.number}</span>`).join('');const state=registrationFailed(session)?'failed':registrationSucceeded(session)?'done':'running';return `<div class="concurrent-flow-account ${state}"><div class="concurrent-flow-head"><strong>${session.batch_index?`#${session.batch_index} · `:''}${escapeHtml(session.email||'等待邮箱')}</strong><span>步骤 ${current?.number||0}/${workflow.total}</span></div><div class="concurrent-flow-current">${current?escapeHtml(current.title):'等待开始'}</div><div class="concurrent-flow-dots">${dots}</div></div>`}).join('')}
