function logLevel(status){const key=String(status||'').toLowerCase();if(registrationFailureStatuses.has(key)||key==='cancelled')return'error';if(['imported','success','completed','done','probe_complete'].includes(key))return'success';if(['waiting_solver','solving_turnstile','waiting_email','queued','paused','pausing'].includes(key))return'warning';return'info'}
function logStep(session,event){const raw=String(event?.message||event?.status||'').toLowerCase();if(isChatgptSession(session)){const steps=chatgptFlowSteps(session);let index=0;if(/sub2api|cpa|绑定分组|绑定配置|站点导入|auto_import/.test(raw))index=8;else if(/auth\.json|转换 agent identity json|认证文件|account save|保存账号/.test(raw))index=7;else if(/agent identity|fetching_sso|session 获取|登录会话|access.?token|\[chatgpt\] session/.test(raw))index=6;else if(/completion|注册成功|registration complete|logged.?in|passkey/.test(raw))index=5;else if(/profile|姓名|生日|个人资料|about-you/.test(raw))index=4;else if(/verification|验证码|\bcode\b|inbox|resend/.test(raw))index=3;else if(/password|密码/.test(raw))index=2;else if(/\[chatgpt\] email|注册邮箱|email:|email=/.test(raw))index=1;else if(registrationFailureStatuses.has(String(event?.status||'').toLowerCase()))index=chatgptFailureStep(session,[raw]);return {number:index+1,title:steps[index].title}}const steps=grokFlowSteps(session);const byKey=Object.fromEntries(steps.map((step,index)=>[step.key,index]));let index=0;if(/导入前测活|pre.?import.*probe|探活|测活|队列测活/.test(raw)&&byKey.probe!==undefined)index=byKey.probe;else if(/sub2api|cpa|绑定分组|站点导入|auto_import|队列导入|手动导入/.test(raw))index=byKey.site;else if(/xai.*json|账号 json|本地账号已保存|认证文件/.test(raw))index=byKey.json;else if(/本地.*pkce|本地.*oauth|at\/rt|local_oauth|授权回调/.test(raw))index=byKey.session;else if(/creating xai account|create_account|创建 grok 账号|创建 xai 账号|xai 浏览器注册成功/.test(raw))index=byKey.account;else if(/verification code|邮箱验证码|code received|fresh code|waiting for xai/.test(raw))index=byKey.verification;else if(/turnstile|captcha|人机验证|过盾/.test(raw))index=byKey.captcha;else if(/password|密码/.test(raw))index=byKey.password;else if(/注册邮箱|email:|email=/.test(raw))index=byKey.email;return {number:index+1,title:steps[index].title}}
function compactLogMessage(message){return String(message||'').split(/\r?\nCall log:/i,1)[0].trim()}
function buildLogEntries(batches,sessions){const entries=[];for(const batch of batches){const at=Number(batch.updated_at||batch.created_at||0);if(at>=logClearBefore)entries.push({key:`batch-${batch.id}-${at}-${batch.message}`,at,status:batch.status,message:compactLogMessage(translateChineseMessage(batch.message||statusName(batch.status))),source:'批次',step:{number:1,title:'打开注册页面'}})}for(const session of sessions){const source=`${isChatgptSession(session)?'ChatGPT':'Grok'}${session.batch_index?` #${session.batch_index}`:''}${session.email?` · ${session.email}`:''}`;const events=Array.isArray(session.events)?session.events:[];for(const event of events){const at=Number(event.at||session.updated_at||0);if(at<logClearBefore)continue;entries.push({key:`${session.id}-${at}-${event.status}-${event.message}`,at,status:event.status||session.status,message:compactLogMessage(translateChineseMessage(event.message||statusName(event.status))),source,step:logStep(session,event)})}}return entries.sort((a,b)=>a.at-b.at).slice(-300)}
function renderLog(entries){const box=document.querySelector('#tasks');document.querySelector('#activity-count').textContent=`${entries.length} 条`;const signature=entries.map(item=>item.key).join('|');if(signature===renderedLogSignature)return;renderedLogSignature=signature;box.innerHTML=entries.length?entries.map(item=>{const level=logLevel(item.status);const step=item.step||{number:1};const time=activityTime(item.at);return `<div class="monitor-log-row ${level}"><span class="monitor-log-message"><time>${escapeHtml(time)}</time><b>步骤 ${step.number}：</b>${escapeHtml(item.message)}</span></div>`}).join(''):'<div class="log-empty">注册日志将在这里自动滚动显示</div>';requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight})}
function renderMonitor(batches,sessions){
  monitorState={batches,sessions};
  renderRegistrationHeaderStats(batches,sessions);
  updatePauseButton(batches);
  const activeSessions=sessions.filter(item=>!terminal(item.status)&&!['paused','cancelled','stopped'].includes(String(item.status||'').toLowerCase()));
  const focus=focusedSession(sessions);
  const displayedSessions=(activeSessions.length?activeSessions:[focus].filter(Boolean)).sort((a,b)=>(Number(a.batch_index||0)-Number(b.batch_index||0))||(Number(a.created_at||0)-Number(b.created_at||0)));
  const workflows=displayedSessions.map(session=>({session,workflow:isChatgptSession(session)?buildChatgptWorkflow(session):buildGrokWorkflow(session)}));
  const workflow=workflows.find(item=>item.session===focus)?.workflow||workflows[0]?.workflow||null;
  const workflowBox=document.querySelector('#workflow-steps');const workflowSignature=`${focus?.id||''}|${workflow?.steps.map(step=>`${step.key}:${step.state}`).join('|')||''}`;if(workflowSignature!==renderedWorkflowSignature){renderedWorkflowSignature=workflowSignature;workflowBox.innerHTML=fixedWorkflowHtml(workflow);requestAnimationFrame(()=>{const failed=workflowBox.querySelector('.monitor-flow-step.failed');const running=[...workflowBox.querySelectorAll('.monitor-flow-step.running')].at(-1);const active=failed||running;if(active)active.scrollIntoView({block:'nearest',inline:'nearest'})})}
  const completedNodes=workflows.reduce((total,item)=>total+item.workflow.completed,0);
  const totalNodes=workflows.reduce((total,item)=>total+item.workflow.total,0);
  document.querySelector('#workflow-progress').textContent=workflows.length>1?`并发 ${workflows.length} · 节点 ${completedNodes}/${totalNodes}`:workflow?`当前账号步骤 ${workflow.completed} / ${workflow.total}`:'当前账号步骤 0 / 0';
  const account=document.querySelector('#workflow-account');
  account.textContent=workflows.length>1?`正在逐账号实时更新 ${workflows.length} 个并发任务`:focus?`当前显示：${isChatgptSession(focus)?'ChatGPT':'Grok'}${focus.batch_index?` · 第 ${focus.batch_index}/${focus.batch_total||'?'} 个`:''} · ${focus.email||'等待邮箱'}`:'尚未创建账号任务';
  const banner=document.querySelector('#workflow-status-banner');
  const bannerText=document.querySelector('#workflow-status-text');
  let tone='idle',label='等待开始注册';
  if(focus){
    if(registrationSucceeded(focus)){tone='success';label='全部节点已完成'}
    else if(registrationFailed(focus)){tone='failed';label=`注册失败${workflow?.failedStep>=0?`：第 ${workflow.failedStep+1} 个节点`:''}`}
    else if(['cancelled','stopped'].includes(String(focus.status||'').toLowerCase())){tone='idle';label='注册已停止'}
    else{tone='running';label=`正在并发注册：${Math.max(1,activeSessions.length)} 个账号`}
  }
  banner.className=`workflow-status-banner ${tone}`;
  bannerText.textContent=label;
  const registration=registrationTotals(batches,sessions);
  const ok=registration.ok;
  const failed=registration.failed;
  const registrationInFlight=batches.length?registration.inflight:activeSessions.length;
  document.querySelector('#summary').textContent=batches.length||sessions.length?`${batches.length} 个批次 · ${sessions.length} 个账号 · 当前注册并发 ${registrationInFlight} · 成功 ${ok} · 失败 ${failed} · ${registrationTiming(batches,sessions,ok)}`:'暂无任务';
  renderManualImportList(sessions);
  renderLog(buildLogEntries(batches,sessions));
}
async function loadDownloadHistory(){const select=document.querySelector('#download-batch');const current=select.value;try{const result=await api('/api/download/history',{cache:'no-store'});const items=result.items||[];select.innerHTML='<option value="">全部成功账号</option>'+items.map(item=>{const parts=[`${escapeHtml(item.date||'未知日期')} · 成功 ${Number(item.count)||0}`];if(Number(item.xai))parts.push(`xAI ${Number(item.xai)}`);if(Number(item.chatgpt))parts.push(`ChatGPT ${Number(item.chatgpt)}`);return `<option value="${escapeHtml(item.date||'')}">${parts.join(' · ')}</option>`}).join('');if([...select.options].some(option=>option.value===current))select.value=current}catch(e){select.innerHTML='<option value="">历史记录加载失败</option>';notify(`历史注册记录加载失败：${e.message}`)}}
async function refresh(){if(refreshInFlight){refreshRequested=true;return refreshInFlight}refreshInFlight=(async()=>{do{refreshRequested=false;try{const local=form.elements.namedItem('mail_provider').value==='hotmail_local';const [r,pool]=await Promise.all([api('/api/sessions',{cache:'no-store'}),local?api('/api/mail/hotmail/accounts',{cache:'no-store'}):Promise.resolve(null)]);const batches=r.batches||[];const sessions=r.sessions||[];renderMonitor(batches,sessions);if(pool)renderHotmailAccounts(pool);if(activeConfigModule==='rotation')await refreshRotation()}catch(e){notify(`刷新失败：${e.message}`)}}while(refreshRequested)})().finally(()=>{refreshInFlight=null});return refreshInFlight}
async function togglePauseCurrent(){const button=document.querySelector('#pause-current');const mode=button.dataset.mode;const statuses=mode==='pause'?batch=>!terminal(batch.status)&&!['paused','pausing'].includes(String(batch.status||'').toLowerCase()):batch=>['paused','cancelled','stopped'].includes(String(batch.status||'').toLowerCase());const targets=monitorState.batches.filter(statuses);if(!mode||!targets.length)return;button.disabled=true;button.textContent=mode==='pause'?'正在暂停…':'正在继续…';try{const results=await Promise.allSettled(targets.map(batch=>api(`/api/batches/${batch.id||batch.batch_id}/${mode}`,{method:'POST'})));const ok=results.filter(result=>result.status==='fulfilled').length;notify(`${mode==='pause'?'暂停':'继续'}请求已提交：${ok}/${targets.length} 个批次`);await refresh()}catch(e){notify(`${mode==='pause'?'暂停':'继续'}失败：${e.message}`)}finally{updatePauseButton(monitorState.batches)}}
function clearMonitorLogs(){logClearBefore=Date.now()/1000;renderedLogSignature='';renderLog([]);notify('当前显示的日志已清空，新日志会继续追加')}
async function resetRound(){if(!await showConfirm('确定清除本轮监控任务吗？\n\n已生成的账号文件不会删除，但清除后无法继续当前暂停批次。'))return;const button=document.querySelector('#reset-round');button.disabled=true;try{const result=await api('/api/sessions/reset',{method:'POST'});notify(`本轮任务已清除：${result.batches_cleared||0} 个批次，${result.sessions_cleared||0} 个会话`);await refresh()}catch(e){notify(`清除失败：${e.message}`)}finally{button.disabled=false}}
async function downloadAccounts(){const button=document.querySelector('#download-accounts');const format=document.querySelector('#download-format').value;const historyDate=document.querySelector('#download-batch').value;button.disabled=true;button.textContent='正在生成…';try{const params=new URLSearchParams({format});if(historyDate)params.set('history_date',historyDate);const response=await fetch(`/api/download?${params}`);if(!response.ok){let detail=`HTTP ${response.status}`;try{const body=await response.json();detail=body.detail||detail}catch{}throw new Error(detail)}const blob=await response.blob();const disposition=response.headers.get('Content-Disposition')||'';const match=disposition.match(/filename="([^"]+)"/);const jsonFormat=['json','cpa_json','sub2api_json','chatgpt_auth_json'].includes(format);const filename=match?.[1]||`progrok_accounts.${jsonFormat?'json':'txt'}`;const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);const count=response.headers.get('X-ProGrok-Account-Count')||'0';const skipped=Number(response.headers.get('X-ProGrok-Skipped-Count')||0);notify(`已下载 ${count} 个账号${skipped?`，跳过 ${skipped} 个缺少必要字段的账号`:''}`)}catch(e){notify(`下载失败：${e.message}`)}finally{button.disabled=false;button.textContent='下载账号'}}
document.querySelector('#tasks').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;b.disabled=true;const action=b.dataset.action||'stop';try{const result=await api(`/api/${b.dataset.type==='batch'?'batches':'sessions'}/${b.dataset.id}/${action}`,{method:'POST'});const messages={pause:'已发送暂停请求',resume:'批次已继续','retry-probe':`已安排 ${result.scheduled??1} 个账号重试测活`,'retry-import':`已安排 ${result.scheduled??1} 个账号重试导入`,stop:'已发送停止请求'};notify(messages[action]||'操作已提交');await refresh()}catch(err){notify(err.message)}finally{b.disabled=false}});
